INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('mcp-github-com-0x4m4-hexstrike-ai','mcp','hexstrike','hexstrike','gh_-244094688032164','gh_158541509','dev_code','approved','2025-10-26T11:27:24Z','2025-11-03T09:11:27Z','2025-10-26T11:27:24Z',replace('HexStrike AI MCP Agents is an advanced MCP server that lets AI agents (Claude, GPT, Copilot, etc.) autonomously run 150+ cybersecurity tools for automated pentesting, vulnerability discovery, bug bounty automation, and security research. Seamlessly bridge LLMs with real-world offensive security capabilities.\n\nwww.hexstrike.com','\n',char(10)),1);
