INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('mcp-github-com-aas-ee-open-websearch','mcp','OpenWebSearch','提供网页搜索及内容抓取功能，支持多引擎检索，并快速获取Linux.do、CSDN、掘金文章和GitHub文档，助您高效收集信息。','gh_-113007432017297','gh_66207760','search_research','approved','2026-02-07T08:00:55Z','2026-02-07T08:00:55Z','2026-02-07T08:00:55Z','提供网页搜索及内容抓取功能，支持多引擎检索，并快速获取Linux.do、CSDN、掘金文章和GitHub文档，助您高效收集信息。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('mcp-github-com-adriyansyah-mf-mcp-pentest','mcp','mcppentest','mcppentest','gh_-12563474683417','gh_158541509','dev_code','approved','2025-10-27T13:43:29Z','2026-03-25T05:33:21Z','2025-10-27T13:43:29Z',replace('MCP Pentest - Automated Penetration Testing Framework\nMCP (Model Context Protocol) server untuk automated penetration testing yang cerdas. Framework ini dapat secara otomatis melakukan reconnaissance, vulnerability scanning, dan controlled exploitation berdasarkan teknologi target yang terdeteksi.','\n',char(10)),1);
