INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('mcp-github-com-muort521-r2aibridge','mcp','Radare2AlBridge','将强大的逆向工程框架 Radare2 集成到 Android 平台，通过本地 HTTP 服务暴露 28 个核心 MCP 工具。','gh_-161240550086431','gh_246210438','dev_code','changes_requested','2026-02-04T16:04:00Z','2026-05-11T15:15:37Z',NULL,replace('将强大的逆向工程框架 Radare2 集成到 Android 平台，通过本地 HTTP 服务暴露 28 个核心 MCP 工具。\n\n核心功能：\n- 深度逆向分析：支持基础(aa)及深度(aaa)分析，智能识别函数、交叉引用(xrefs)和字符串。\n- 动态调试与模拟：支持模拟执行(ESIL)、反汇编、反编译及二进制 Patch。\n- 系统级工具：集成 Logcat 日志读取、文件系统操作(支持 Root)、Termux 命令执行及 SQL 查询。\n- AI 辅助增强：支持智能重命名函数、添加知识库笔记及批量解密混淆字符串。\n- 服务特性：后台 Ktor 服务器(端口 5050)，支持并发管理与多客户端接入。','\n',char(10)),1);
