INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-diary','package','📔 角色日记本','角色日记本插件，从DSL框架更新至WebView，拥有个人日记、交换日记、私密日记三大板块，以及自定义主题、气泡、字体修改、书写日记界面时间等等功能','gh_143613684','gh_143613684','dev_code','withdrawn','2026-05-01T10:59:48Z','2026-07-22T03:12:15.429Z','2026-07-05T05:36:08.788Z',replace('修正了ai填写作者的问题，目前会主动引导ai不清楚的情况下填写character，插件内部自转换为角色卡名字\n添加了修改工具，可以修改日记作者名了\n-\n作者代码白痴，概率有问题，请在知晓此前提下使用\n在小红书发了帖，请求bug反馈。如有bug请联系，我会提供deepseek的api key，麻烦您给我ds查出的bug来源以便我修改……\n‼️自己修改，请一定让机备份记录\n\n如有bug请联系：\n小红书@黒羽 燕\nQQ 2094143735（请不要发邮件，申请好友即可）','\n',char(10)),1);
