INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-learning-mode-bundle','package','学习模式','通用 AI 导师系统：渐进式学习 Agent，支持动态课程规划、智能考核、错题复盘、难度自适应和长期学习跟踪。通过侧边栏开关控制学习模式开关，开启后自动注入导师提示词。','gh_75722052','gh_75722052','docs_knowledge','approved','2026-05-29T02:41:26Z','2026-05-30T01:45:38Z','2026-05-29T02:41:26Z','通用 AI 导师系统：渐进式学习 Agent，支持动态课程规划、智能考核、错题复盘、难度自适应和长期学习跟踪。通过侧边栏开关控制学习模式开关，开启后自动注入导师提示词。已经稳定测试多轮，后续将引入外部资料降低幻觉。欢迎评论区反馈',1);
