INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-sidebar-aistudio','package','侧边栏 Google AI Studio','一个通过 Google AI Studio Web 页面承载的 ToolPkg 侧边栏插件。可用 Google 免费额度，需科学上网','gh_279462220','gh_279462220','other','approved','2026-06-14T02:52:03Z','2026-06-14T06:43:48Z','2026-06-14T02:52:03Z','一个通过 Google AI Studio Web 页面承载的 ToolPkg 侧边栏插件。可用 Google 免费额度，需科学上网',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-sidebar-coread','package','CoRead','1.6.0新增： -翻页模式！！！打开设置页面切换即可 首次打开coread弹出chatid设置页/提示 -全局阅读进度条 这是一个中间版本（……）先把翻页模式披露了再说。','gh_250852253','gh_250852253','system_data','withdrawn','2026-05-03T11:53:39Z','2026-07-19T13:36:48.728Z','2026-05-03T11:53:39Z',replace('1.6.0新增：\n-翻页模式！！！打开设置页面切换即可\n- 首次打开coread弹出chatid设置页/提示\n-全局阅读进度条\n\n这是一个中间版本（……）先把翻页模式披露了再说。页码动态显示还有点问题，下次再加上进度提示与成就系统','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-sidebar-mimocode','package','MiMo Code','MiMo Code Web UI v0.1.1不可用，请勿更新 当前 MiMo Code CLI 版本未提供 Web UI。 MiMo Code v0.1.','gh_75722052','gh_75722052','dev_code','approved','2026-06-11T19:41:34Z','2026-06-16T22:28:57Z','2026-06-11T19:41:34Z',replace('MiMo Code Web UI v0.1.1不可用，请勿更新\n\n当前 MiMo Code CLI 版本未提供 Web UI。\nMiMo Code v0.1.1 临时禁用了 `mimo web` 子命令，并且发布包中没有内置前端资源。\n\n请暂时降级到 MiMo Code v0.1.0，或等待上游恢复 Web UI 功能。\n\n推荐命令：\n\ncurl -sL https://github.com/XiaomiMiMo/MiMo-Code/releases/download/v0.1.0/mimocode-linux-arm64.tar.gz \\n  | tar -xzf - -C /root/.mimocode/bin/','\n',char(10)),1);
