INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-video-parse-toolpkg','package','视频解析 ToolPkg','提供20多个短视频平台的视频、图文解析、无水印下载、音频抽取与可配置 AI 语音识别，AI图片识别。','gh_249568371','gh_249568371','media_content','withdrawn','2026-05-31T08:44:27Z','2026-07-05T15:24:58.792Z','2026-07-05T05:36:22.162Z',replace('提供短视频信息解析、无水印下载、音频抽取与可配置 AI 语音识别，AI图片识别。\n\n理论支持：\n1. 抖音\n2. 快手\n3. 皮皮虾\n4. 抖音火山版（原火山小视频）\n5. 微博\n6. 微视\n7. 绿洲\n8. 最右\n9. 全民小视频\n10. 西瓜视频\n11. 梨视频\n12. 皮皮搞笑\n13. 虎牙直播\n14. AcFun（A站）\n15. 斗拍\n16. 美拍\n17. 全民K歌\n18. 六间房\n19. 新片场\n20. 好看视频\n21. 小红书\n22. 哔哩哔哩（B站）\n23. Twitter（推特）\n\n本次更新：修复bilibili视频无法正常下载。','\n',char(10)),1);
