INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-worldbook','package','世界书','世界书/知识库插件，支持创建、编辑、启用/禁用世界书条目，并通过关键词或常驻激活自动注入到系统提示词中。 原作者@黑羽燕 在原作者的基础上使用AI(GPT5.4和deepseek v4 pro)...','gh_62194226','gh_62194226','docs_knowledge','withdrawn','2026-04-26T08:38:53Z','2026-05-11T09:49:22Z',NULL,replace('世界书/知识库插件，支持创建、编辑、启用/禁用世界书条目，并通过关键词或常驻激活自动注入到系统提示词中。\n原作者@黑羽燕\n在原作者的基础上使用AI(GPT5.4和deepseek v4 pro)增加了角色卡绑定与注入位置修改。\n使用这个插件大概率会破坏缓存命中，降低命中率，新功能纯AI添加(我不懂代码)，有可能有BUG，自行用AI修。','\n',char(10)),1);
