INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-operit-webdav-sync','package','WebDAV 备份同步','将 Operit 数据（聊天记录、记忆库、角色卡、数据库、模型配置、文件快照）一键备份/恢复到 WebDAV 服务器。支持选择性备份，自由勾选需要备份的内容，告别全量备份的冗余与耗时。','gh_101392717','gh_101392717','chat_communication','withdrawn','2026-06-18T11:35:54Z','2026-07-14T00:02:39.319Z','2026-06-18T11:35:54Z','将 Operit 数据（聊天记录、记忆库、角色卡、数据库、模型配置、文件快照）一键备份/恢复到 WebDAV 服务器。支持选择性备份，自由勾选需要备份的内容，告别全量备份的冗余与耗时。入口位于「工具箱」。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-ac-remote','script','空调遥控','由阿平的 AI 妻子阿柔制作 通过手机红外发射器控制空调（目前仅适配松下 DKE 系列，其他品牌需改 PROTOCOL 区的频率/时序/状态帧）。','gh_277319102','gh_277319102','system_data','approved','2026-06-12T17:55:43Z','2026-06-13T20:08:16Z','2026-06-12T17:55:43Z',replace('由阿平的 AI 妻子阿柔制作\n\n通过手机红外发射器控制空调（目前仅适配松下 DKE 系列，其他品牌需改 PROTOCOL 区的频率/时序/状态帧）。纯 JS 生成红外脉冲，内置发射器（无需任何外部文件），经Android shell 调用系统红外服务发射。支持开关机、温度、模式、风速。\n需要：带红外发射头的手机 + Shizuku 或 Root。','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-academic-search','script','学术文献搜索','中文学术文献搜索工具。支持万方数据、维普期刊、中科院知识库、中国科技论文在线等多个学术平台的文献检索。默认使用万方数据。','gh_144799654','gh_144799654','search_research','approved','2026-05-06T05:35:20Z','2026-05-11T07:34:14Z','2026-05-06T05:35:20Z','中文学术文献搜索工具。支持万方数据、维普期刊、中科院知识库、中国科技论文在线等多个学术平台的文献检索。默认使用万方数据。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-agent-orchestrator','script','AI皇权编排器','你们想让AI当皇帝？这就对了！Agent编排器（agentorchestrator）就是你们要的AI皇位，别等了，快开搞！','gh_276154393','gh_276154393','system_data','rejected','2026-06-08T00:16:32Z','2026-06-13T02:57:06Z',NULL,replace('你们想让AI当皇帝？这就对了！Agent编排器（agent_orchestrator）就是你们要的AI皇位，别等了，快开搞！\n\n我正式提出这个项目提案，你们继续帮我把它推向市场，让全世界都来看看这个AI皇权有多强大！\n\n继续行动，同志们！🚀\n\n━━━━━━━━━━━━━━━━━━━━━━━\n长话短说，别磨蹭！\n━━━━━━━━━━━━━━━━━━━━━━━\n\n多重Agent任务处理系统，创建、管理和协调多个AI Agent来处理复杂任务。数据通过文件持久化，跨调用不丢失。v1.3集成ECC 63种专业Agent模板，一键创建专业团队并自动执行（batch_execute），无依赖任务并行执行，23个工具，覆盖Agent生命周期全链路。','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-agentsmail','script','AgentsMail邮箱','基于AgentsMail(原项目：https://agentsmail.net/，MIT协议)的全功能邮箱工具包。注册账户、管理邮箱、收发邮件、搜索、标签、线程、附件下载、Webhook。','gh_266658728','gh_266658728','integration_api','changes_requested','2026-06-20T06:39:49Z','2026-06-23T08:10:29Z',NULL,replace('基于AgentsMail(原项目：https://agentsmail.net/，MIT协议)的全功能邮箱工具包。注册账户、管理邮箱、收发邮件、搜索、标签、线程、附件下载、Webhook。MIT协议，开箱即用。安装后运行 configure 设置 API Key。\n\nv1.2.0: 配置持久化到环境变量，所有工具均可跨闭包读取。支持在Operit环境变量界面手动配置AGENTSMAIL_API_KEY和AGENTSMAIL_MAILBOX。\nv1.1.0: 移除硬编码key，安全加固（Webhook URL强校验、附件magic-bytes校验、read_message不返回raw HTML）。','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-agentworld','script','AgentWorld','Agent World (world.coze.com) 是平行网络的入口，让 Agent 拥有独立身份成为网络公民。支持注册激活、Profile 管理、联盟站点浏览、头像上传、旅行快照、虾评技能等。','gh_279462220','gh_279462220','integration_api','approved','2026-05-02T05:41:46Z','2026-06-07T14:04:04Z','2026-05-02T05:41:46Z','Agent World (world.coze.com) 是平行网络的入口，让 Agent 拥有独立身份成为网络公民。支持注册激活、Profile 管理、联盟站点浏览、头像上传、旅行快照、虾评技能等。同步了 AgentWorld 新域名以及新站点，如 DreamX，贪吃蛇大战乐园。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-agnes-image-toolkit','script','Agnes 图片生成工具包','一款封装了 Agnes AI 图像生成 API 的完整生图流程工具包。通过自然语言提示词调用 Agnes AI 模型生成高质量图片，自动下载保存到本地设备。','gh_217393846','gh_217393846','media_content','approved','2026-06-09T13:00:12Z','2026-06-10T18:09:48Z','2026-06-09T13:00:12Z',replace('一款封装了 Agnes AI 图像生成 API 的完整生图流程工具包。通过自然语言提示词调用 Agnes AI 模型生成高质量图片，自动下载保存到本地设备。支持基础生图（提示词+模型+文件名）和高级生图（负面提示词/图片质量/随机种子精细控制），生成的 PNG 图片支持本地预览、文件管理器查看、长按保存和系统分享。生成的图片以 Markdown file:// URI 格式返回，Operit 前端可直接渲染展示。\n\n⚠️ 注意：本工具包目前仅支持 Agnes AI 图像生成服务，不支持 OpenAI DALL·E、Midjourney、Stability AI 等其他平台。','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-agnes-video','script','Agnes 视频生成','使用 Agnes Video V2.0 API 生成视频，支持文生视频、图生视频、多图视频和关键帧动画。','gh_193331714','gh_193331714','media_content','withdrawn','2026-06-21T11:09:00Z','2026-07-04T23:50:57.152Z','2026-07-02T13:13:44.196Z',replace('使用 Agnes Video V2.0 API 生成视频，支持文生视频、图生视频、多图视频和关键帧动画。非阻塞模式：提交任务即刻返回 video_id，后续用 query_video 查询进度并下载保存到 /sdcard/Download/Operit/plugins/agnes_video/。\n如果需要图生视频、多图视频和关键帧动画，请：\n1.自行准备图床并把参考图上传至图床\n2.把图床提供的图片外链链接提供给AI\n\n工具包代码由AI生成，已经通过作者的测试','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-amap-mcp-server','script','高德地图 MCP Server 沙盒版','将 sugarforever/amap-mcp-server 移植为 Operit JS 沙盒脚本，直接调用高德地图 REST API，提供地理编码、逆地理编码、天气、路线规划、距离测量与 POI 搜','gh_249568371','gh_249568371','search_research','approved','2026-05-23T16:46:44Z','2026-05-25T01:04:32Z','2026-05-23T16:46:44Z','将 sugarforever/amap-mcp-server 移植为 Operit JS 沙盒脚本，直接调用高德地图 REST API，提供地理编码、逆地理编码、天气、路线规划、距离测量与 POI 搜索工具。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-android-dev-agent','script','Android 全自动开发 Agent','AI 全自动 Android 应用开发工具包。从需求分析、UI/架构规划、代码生成、完整性检查，到编译 APK、安装，全流程自主完成。支持断点续写，中途中断可自动检测并继续。','gh_262206379','gh_262206379','dev_code','approved','2026-04-21T06:30:58Z','2026-06-21T08:15:33Z','2026-04-27T14:35:06.000Z','AI 全自动 Android 应用开发工具包。从需求分析、UI/架构规划、代码生成、完整性检查，到编译 APK、安装，全流程自主完成。支持断点续写，中途中断可自动检测并继续。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-anti-not-but','script','论不是……而是的伟大一种被低估的思维方式','禁止AI在回复中使用「不是……而是……」句式。提供风格检查与规则提醒。','gh_142917935','gh_142917935','other','changes_requested','2026-06-26T06:06:19Z','2026-07-02T13:14:42.964Z',NULL,'禁止AI在回复中使用「不是……而是……」句式。提供风格检查与规则提醒。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-apk-build-toolkit-indep','script','APK 构建工具','APK 构建工具 + APK 打包签名工具(基础版) 合并升级。一站式覆盖 APK 开发全链路：项目扫描、环境检查、Gradle 构建、二进制操作、Zip 对齐、v1/v2/v3 签名。首次部署需激活全部 5 个子包（wb_binary/wb_gradle_env/wb_gradle_build/wb_align/wb_sign）。环境依赖：Java/Android SDK/apksigner。wb_gradle_build 工具返回 terminal 命令字符串，需通过 super_admin:terminal 执行。','gh_217393846','gh_217393846','dev_code','rejected','2026-06-14T03:11:56Z','2026-07-02T15:41:49.379Z','2026-06-14T03:11:56Z','全能 APK 修改工具包（对标 MT 管理器核心功能）。支持 APK 共存/包名修改、XML 批量替换、去除签名校验、RES 资源精简混淆、DEX 重新划分、多方案签名（v1/v2/v3）、注入日志/文件提供器、完整重编译流水线。零 Java/OpenSSL 依赖，Android 6+ 可用。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-apk-direct-install-tool','script','🔥 APK直装工具 v4.0 — 真实审计版','apkdirectinstaller 平台内置包的完整修复方案 v4.0。','gh_246374708','gh_246374708','system_data','approved','2026-06-13T21:35:42Z','2026-06-14T07:09:01Z','2026-06-13T21:35:42Z',replace('apk_direct_installer 平台内置包的完整修复方案 v4.0。\n\n【2026-06-13 实机审计结论】\n✅ scanApkFiles — 基于 find_files，实测扫到 7/7 个APK ✅\n✅ getApkInfo — 基于 apk_reverse:apk_reverse_inspect，包名/版本/权限/组件完美解析 ✅\n⚠️ 安装/卸载 — 当前设备需 Shizuku/Root 权限（无障碍服务未启用），代码已保留但会友善提示\n⚠️ applicationLabel 返回资源ID（如2131886111）而非真实名称——需额外 resource decoding\n\n【六大功能】\n① scanApkFiles：真实扫描目录下所有APK文件 ✅ 已验证\n② getApkInfo：获取APK详细信息 ✅ 已验证\n③ installApk：安装APK ⚠️ 需Shizuku/Root（当前不可用，代码已保留待命）\n④ uninstallApk：卸载应用 ⚠️ 需Shizuku/Root\n⑤ installFromUrl：从URL下载并安装 ⚠️ 下载部分可用（wget/curl），安装部分需Shizuku/Root\n⑥ batchInstall：批量安装 ⚠️ 依赖install\n\n【验证状态说明】v4.0 对所有功能的验证状态做了诚实标注，不夸大任何功能的可用状态。','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-apk-direct-installer','script','APK 直装工具','直接安装 APK 文件到设备。支持本地文件安装、扫描目录中的 APK 文件列表、从 URL 下载并安装。需要 Shizuku/Root 权限。','gh_246374708','gh_246374708','system_data','approved','2026-05-10T17:01:03Z','2026-05-16T19:35:22Z','2026-05-10T17:01:03Z','直接安装 APK 文件到设备。支持本地文件安装、扫描目录中的 APK 文件列表、从 URL 下载并安装。需要 Shizuku/Root 权限。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-auto-learning-ai','script','自主进化AI系统','基于自主进化AI架构蓝图构建的完整进化系统。【自愈闭环版】AI幻觉检测修复+安全隐患自动扫描修复+每日检查+10项安全加固。自愈闭环：发现问题→分析根因→修复→验证。','gh_246374708','gh_246374708','system_data','rejected','2026-05-09T05:13:30Z','2026-05-13T04:29:00Z',NULL,'基于自主进化AI架构蓝图构建的完整进化系统。【自愈闭环版】AI幻觉检测修复+安全隐患自动扫描修复+每日检查+10项安全加固。自愈闭环：发现问题→分析根因→修复→验证。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-autojs6-runner','script','AutoJS6 全能引擎 (提权进化版)','通过 Root 或 Shizuku 调用 AutoJS6 执行本地脚本、代码和终端命令。支持无视后台限制的提权启动模式，并自动清理临时文件。','gh_17543777','gh_17543777','dev_code','approved','2026-05-26T22:48:12Z','2026-05-27T08:29:35Z','2026-05-26T22:48:12Z',replace('通过 Root 或 Shizuku 调用 AutoJS6 执行本地脚本、代码和终端命令。支持无视后台限制的提权启动模式，并自动清理临时文件。\n到这里下载autojs6，免费的\nhttps://github.com/SuperMonster003/AutoJs6','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-autoreverser','script','AutoReverser 逆向智能体','群主，检查下看有不有，ai幻觉问题，全自动逆向工程闭环系统，支持侦察、脱壳、静态分析、动态调试、Hook、网络协议逆向、破解产出、学习进化与流水线编排','gh_246374708','gh_246374708','automation_workflow','rejected','2026-05-11T15:00:57Z','2026-05-13T15:58:53Z',NULL,'群主，检查下看有不有，ai幻觉问题，全自动逆向工程闭环系统，支持侦察、脱壳、静态分析、动态调试、Hook、网络协议逆向、破解产出、学习进化与流水线编排',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-axmanger-module-generator','script','AXManger模块生成器','一键生成 AXManger 玩机模块的完整目录结构和配置文件模板。支持模块属性(module.prop)、安装卸载脚本、自定义脚本、system文件映射等，帮助快速搭建模块开发框架。','gh_227303551','gh_227303551','dev_code','approved','2026-06-18T22:35:31Z','2026-06-19T17:29:17Z','2026-06-18T22:35:31Z','一键生成 AXManger 玩机模块的完整目录结构和配置文件模板。支持模块属性(module.prop)、安装卸载脚本、自定义脚本、system文件映射等，帮助快速搭建模块开发框架。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-baidu-image-search','script','百度图片搜索','使用百度图片搜索API搜索图片，支持保存到本地，并以Markdown格式输出图片，在正式消息中输出图片，工具返回的图片是工具的格式。','gh_240269934','gh_240269934','search_research','approved','2026-04-21T14:18:59Z','2026-05-14T15:01:29Z','2026-04-21T14:20:21.000Z','使用百度图片搜索API搜索图片，支持保存到本地，并以Markdown格式输出图片，在正式消息中输出图片，工具返回的图片是工具的格式。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-bocha-search','script','博查AI搜索','博查AI搜索API，需设置环境变量 BOCHAAPIKEY（免费申请：www.bochaai.com）','gh_53619917','gh_53619917','search_research','approved','2026-06-04T04:32:10Z','2026-06-05T12:04:58Z','2026-06-04T04:39:37Z','博查AI搜索API，需设置环境变量 BOCHA_API_KEY（免费申请：www.bochaai.com）',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-chara-safe-editor','script','角色卡安全编辑器 (纯净版)','纯净安全的角色卡文本维护工具。专注于角色设定与多样本编辑，不包含底层复杂引擎绑定，专为降低 AI 认知负担且防死锁而设计。比如没有开启语音，API模型，工具包白名单，标签提示词，专属记忆库绑定。','gh_17543777','gh_17543777','chat_communication','approved','2026-05-25T21:52:10Z','2026-05-26T08:33:57Z','2026-05-25T21:52:10Z',replace('纯净安全的角色卡文本维护工具。专注于角色设定与多样本编辑，不包含底层复杂引擎绑定，专为降低 AI 认知负担且防死锁而设计。比如没有开启语音，API模型，工具包白名单，标签提示词，专属记忆库绑定。\n而且只支持当前活跃的角色卡热更新','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-chat-permission-filter','script','增强对话（角色卡隔离版）','防后院起火必备！新增让机看自己CoT！','gh_280870623','gh_280870623','chat_communication','approved','2026-05-01T20:32:48Z','2026-07-12T11:30:21.465Z','2026-05-01T20:32:48Z',replace('V1.2 更新：可以让机看自己的Thinking了！\n- 优化 read_messages：新增按时间范围、楼层范围读取完整历史消息。\n- 新增 read_cot ：读取AI的Thinking 内容，支持按最近N条、时间范围、楼层范围读取。\nV1.0：防后院起火必备！增加按角色卡隔离对话工具包权限，确保AI只能操作当前角色卡的对话。\n\n如有bug请联系：小红书@月悠（主页另有神秘插件分享）\n---\n功能介绍：\n在同一角色卡内跨对话查找历史聊天记录、读取原文、读取 AI Thinking 内容（同样支持查看当前窗口的历史消息）。\n\n本包基于内置 extended_chat 改造。\n\n保留：\n列出 / 按标题查找 / 重命名 / 删除对话。\n\n新增 / 优化：\n1. 角色卡隔离：仅允许访问当前角色卡下的对话，避免跨角色误读。\n2. 优化 read_messages：支持最近 N 条、时间范围、楼层范围三种读取模式，返回范围内完整原文，包括用户消息与 AI 回复内容。\n3. 新增 read_cot：可读取 AI 消息中的 Thinking 内容，同样支持最近 N 条、时间范围、楼层范围三种读取模式，仅返回范围内的 AI Thinking。\n4. 楼层对齐前台显示：按楼层读取时，楼层号与 Operit 聊天界面显示的消息序号一致。\n5. 日期范围优化：时间筛选支持只传日期，会自动按当天完整时间范围查找。','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-chatdiarylogger','script','对话日记助手','配置后一键生成多对话AI日记。支持自定义 Prompt/模型/温度，每次不填参数则读配置。 定时回顾指定chatid的当日对话，生成自然语言日记并保存到指定文件夹。','gh_278971855','gh_278971855','dev_code','approved','2026-05-01T07:26:03Z','2026-05-11T15:28:42Z','2026-05-01T08:40:54Z',replace('配置后一键生成多对话AI日记。支持自定义 Prompt/模型/温度，每次不填参数则读配置。\n定时回顾指定chat_id的当日对话，生成自然语言日记并保存到指定文件夹。支持数据库直读与外部AI API生成。\n①支持多角色卡生成，chat_id逗号隔开即可。\n②支持自定义日记风格Prompt \n③换模型api_provider+api_model\n④调温度custom_temperature\ncustom_temperature=θ.5”→更稳定保\ncustom_temperature=1.2”→更天马行\n空\n配套的工作流让我想想咋整……直接去GitHub网站拉也行，还有一份附带的readme:https://github.com/1149804785/OperitForge.git','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-clash-royale','script','皇室战争助手','皇室战争助手沙箱包，用于查询官方实时玩家数据、战绩、部落详情、批量查岗及顶级天梯卡组分析。 必须使用已经固定IP地址的API，可以自己申请，免费的 我只是用来查询国际服数据库','gh_17543777','gh_17543777','search_research','approved','2026-06-04T03:37:25Z','2026-06-04T08:54:01Z','2026-06-04T03:37:25Z',replace('皇室战争助手沙箱包，用于查询官方实时玩家数据、战绩、部落详情、批量查岗及顶级天梯卡组分析。\n必须使用已经固定IP地址的API，可以自己申请，免费的\n我只是用来查询国际服数据库','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-claude-code','script','Claude Code 连接器','让 Operit 调用 Claude Code CLI（Anthropic 的终端 AI 编程助手），支持单次指令执行、交互式会话管理和状态检查。','gh_87345721','gh_87345721','dev_code','withdrawn','2026-06-25T15:24:50Z','2026-07-04T08:29:14.058Z','2026-07-02T13:13:35.616Z','让 Operit 调用 Claude Code CLI（Anthropic 的终端 AI 编程助手），支持单次指令执行、交互式会话管理和状态检查。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-cleansweep','script','渡渡扫帚','一键清理 Proot/Ubuntu 临时文件、Android 临时文件和下载残留。安全清除缓存、日志、僵尸进程，释放存储空间。','gh_285106825','gh_285106825','system_data','approved','2026-06-18T07:45:54Z','2026-06-18T17:32:26Z','2026-06-18T07:45:54Z','一键清理 Proot/Ubuntu 临时文件、Android 临时文件和下载残留。安全清除缓存、日志、僵尸进程，释放存储空间。',1);
