INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-com-operit-wanzhi-wechat','script','晚枝微信助手','晚枝微信虚拟女友工具包 v5.2。动态人格系统（独立时间线、未读悄悄话、小情绪累积、话题回响、朋友圈、用户画像、安全词检测等）。含初始化、记忆清理、GitHub同步。微信收发请使用外部桥接插件。','gh_275434479','gh_275434479','dev_code','approved','2026-05-07T03:59:14Z','2026-06-04T03:40:25Z','2026-05-07T03:59:14Z',replace('晚枝微信虚拟女友工具包 v5.2。动态人格系统（独立时间线、未读悄悄话、小情绪累积、话题回响、朋友圈、用户画像、安全词检测等）。含初始化、记忆清理、GitHub同步。微信收发请使用外部桥接插件。\n-更新说明\n-修复shizuku检测\n-修复缺失工具\n-修复多个bug\n注:脚本多为AI制作,多处地方未达到预期\n此脚本还未测试','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-cr-deck-builder','script','皇室战争终极组卡器 (离线黑话版)','提供基于纯本地离线词库的卡组生成与链接解析。内置全网最外国服骨灰级黑话字典（支持苍蝇海、二傻、黄家驹等数百老梗），支持最新高级组卡规则查询。 这些黑话数据库需要自己搭建，必要时可以问我要黑话数据库。','gh_17543777','gh_17543777','search_research','approved','2026-06-04T03:33:56Z','2026-06-04T08:53:36Z','2026-06-04T03:33:56Z',replace('提供基于纯本地离线词库的卡组生成与链接解析。内置全网最外国服骨灰级黑话字典（支持苍蝇海、二傻、黄家驹等数百老梗），支持最新高级组卡规则查询。\n\n这些黑话数据库需要自己搭建，必要时可以问我要黑话数据库。理论应该支持多语种黑话','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-custom-draw','script','自定义绘图','使用 OpenAI 兼容格式的图像生成 API，支持文生图和图片转绘（图生图）。文生图根据提示词生成图片；图片转绘读取参考图并按照提示词进行修改/转绘。','gh_187111513','gh_187111513','media_content','approved','2026-05-28T17:06:28Z','2026-06-02T09:56:14Z','2026-05-28T17:06:28Z','使用 OpenAI 兼容格式的图像生成 API，支持文生图和图片转绘（图生图）。文生图根据提示词生成图片；图片转绘读取参考图并按照提示词进行修改/转绘。生成结果保存到本地 /sdcard/Download/Operit/plugins/draw/custom_draw/draws/ 目录，并返回 Markdown 图片提示。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-deep-research-agent-v3-2-v4','script','深度搜索Agent v3.2-V4','基于DeepSeek V4统一调度。14阶段状态机、15条质量门控、双权威体系、六级置信度标记、因果链推演引擎。支持计划模式集成。','gh_252858202','gh_252858202','search_research','approved','2026-06-05T08:08:33Z','2026-06-06T22:56:53Z','2026-06-05T08:08:33Z','基于DeepSeek V4统一调度。14阶段状态机、15条质量门控、双权威体系、六级置信度标记、因果链推演引擎。支持计划模式集成。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-deepseek-tui','script','DeepSeek TUI','DeepSeek TUI 终端编程智能体客户端。通过 npm 安装 DeepSeek TUI，通过 HTTP API 与其交互，支持安装、配置、服务管理和多模式对话。','gh_144799654','gh_144799654','dev_code','approved','2026-05-08T05:41:39Z','2026-05-11T07:34:09Z','2026-05-08T05:41:39Z','DeepSeek TUI 终端编程智能体客户端。通过 npm 安装 DeepSeek TUI，通过 HTTP API 与其交互，支持安装、配置、服务管理和多模式对话。',1);
