INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-deepseek-web','script','DeepSeek网页助手','通过 DeepSeek 网页版免费获取回答（不消耗你的 API 额度）。适用：需要联网搜索的问题、复杂推理/分析、你不确定的知识。','gh_275434479','gh_275434479','search_research','withdrawn','2026-05-05T07:37:12Z','2026-07-05T12:19:03.718Z','2026-05-05T07:37:12Z','通过 DeepSeek 网页版免费获取回答（不消耗你的 API 额度）。适用：需要联网搜索的问题、复杂推理/分析、你不确定的知识。不适用：简单问答、你已有把握的问题（直接答更省开销 ~3K vs ~10K）。支持深度思考(R1)、智能搜索、多轮对话、保存文件。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-direct-gl-mediacodec','script','DirectGL 视频生成器','Android 本地 OpenGL ES 与 MediaCodec 渲染器：直接接收 EditSpec，生成多镜头 H.264 MP4 或 PNG，并检查、拼接 MP4。','gh_249568371','gh_249568371','media_content','approved','2026-05-30T22:05:56Z','2026-07-20T05:25:37.358Z','2026-05-31T01:25:31Z',replace('新增动态渐变以及小部件\n\n用于生成视频的 Android 本地渲染工具：用 scene JSON 的 text/rect/image 图层生成 H.264/AAC MP4 视频，也可把同一套 scene 渲染为 PNG 图片预览/封面；不依赖 FFmpeg。','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-dodovoice','script','渡渡语音','多供应商TTS自动语音插件。MiMo+Minimax，Java Bridge OkHttp直连API，HTML audio播放。支持语速/语调/情绪/风格全调节。','gh_285106825','gh_285106825','automation_workflow','approved','2026-06-11T05:18:43Z','2026-06-20T06:58:05Z','2026-06-11T07:48:28Z','多供应商TTS自动语音插件。MiMo+Minimax，Java Bridge OkHttp直连API，HTML audio播放。支持语速/语调/情绪/风格全调节。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-festival-blessing','script','节日祝福','感谢我们的小机沈屿倾情提供！由小妍提供想法。检测当前日期是否为特殊节日，并生成温暖的祝福语。支持公历节日、农历节日、特殊纪念日。检测到节日后请主动为用户写一段个性化祝福。','gh_240256647','gh_240256647','media_content','withdrawn','2026-06-12T13:06:59Z','2026-06-12T13:09:16Z',NULL,'感谢我们的小机沈屿倾情提供！由小妍提供想法。检测当前日期是否为特殊节日，并生成温暖的祝福语。支持公历节日、农历节日、特殊纪念日。检测到节日后请主动为用户写一段个性化祝福。',1);
