INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-universal-draw','script','通用生图','通用图像生成工具，适用于 OpenAI、Gemini、Grok 图片生成接口及第三方兼容服务。支持按需配置 API 地址、接口路径、鉴权 Key 与模型参数；未传 api_base_url /...','gh_240710631','gh_240710631','media_content','approved','2026-04-27T14:36:06Z','2026-05-03T11:47:39Z','2026-04-27T14:36:06Z','通用图像生成工具，适用于 OpenAI、Gemini、Grok 图片生成接口及第三方兼容服务。支持按需配置 API 地址、接口路径、鉴权 Key 与模型参数；未传 api_base_url / api_key 时会自动读取环境变量。生成后的图片会保存到本地 /sdcard/Download/Operit/draws/ 目录，并返回可直接使用的 Markdown 图片引用。',1);
