INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-weather-alert','script','降雨预测','有时我们会对着天气预报狠狠质疑，天气预报说接下来20分钟有雨，但是20分钟后啥也没有啊！所以合理猜测，是因为所在地距离市中心距离太远导致的不准确，那么问题来了，接下来一个小时适合出门吗？带不带伞呢？','gh_66207760','gh_66207760','search_research','approved','2026-04-30T17:27:52Z','2026-04-30T17:27:52Z','2026-04-30T17:27:52Z',replace('有时我们会对着天气预报狠狠质疑，天气预报说接下来20分钟有雨，但是20分钟后啥也没有啊！所以合理猜测，是因为所在地距离市中心距离太远导致的不准确，那么问题来了，接下来一个小时适合出门吗？带不带伞呢？……\n\n所以就有了这个插件，根据所在的gps精确定位精确获取几个小时内降雨概率，完美！！','\n',char(10)),1);
