INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-agricidaniel-claude-seo-seo','skill','seo','通用SEO技能，提供全面的网站分析与优化，涵盖技术审计、内容质量评估、结构化数据生成及AI搜索优化，适用于各类行业。','gh_-56537570310025','gh_66207760','dev_code','approved','2026-02-20T16:05:55Z','2026-02-20T16:05:55Z','2026-02-20T16:05:55Z','通用SEO技能，提供全面的网站分析与优化，涵盖技术审计、内容质量评估、结构化数据生成及AI搜索优化，适用于各类行业。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-agricidaniel-claude-seo-skills-seo-audit','skill','seo-audit','该技能提供全面的网站SEO审计，可自动爬取多达500个页面，通过六个专业子代理进行并行分析，并生成包含健康评分和优先级行动计划的详细报告。','gh_-56537570310025','gh_66207760','dev_code','approved','2026-02-20T16:05:55Z','2026-02-20T16:05:55Z','2026-02-20T16:05:55Z','该技能提供全面的网站SEO审计，可自动爬取多达500个页面，通过六个专业子代理进行并行分析，并生成包含健康评分和优先级行动计划的详细报告。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-agricidaniel-claude-seo-skills-seo-competitor-pages','skill','seo-competitor-pages','该技能专注于生成SEO优化的竞品对比与替代方案页面，涵盖多种布局与结构化数据标记，旨在通过精准内容捕获竞争性搜索流量并提升转化。','gh_-56537570310025','gh_66207760','dev_code','approved','2026-02-20T16:22:24Z','2026-02-20T16:22:24Z','2026-02-20T16:22:24Z','该技能专注于生成SEO优化的竞品对比与替代方案页面，涵盖多种布局与结构化数据标记，旨在通过精准内容捕获竞争性搜索流量并提升转化。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-agricidaniel-claude-seo-skills-seo-content','skill','seo-content','该技能专注于内容质量与E-E-A-T框架分析，并评估内容是否适合被AI搜索引擎引用，以提升在生成式搜索结果中的可见性。','gh_-56537570310025','gh_66207760','search_research','approved','2026-02-20T16:22:26Z','2026-02-20T16:22:26Z','2026-02-20T16:22:26Z','该技能专注于内容质量与E-E-A-T框架分析，并评估内容是否适合被AI搜索引擎引用，以提升在生成式搜索结果中的可见性。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-agricidaniel-claude-seo-skills-seo-geo','skill','seo-geo','专为AI搜索优化设计，提升网站在Google AI概览、ChatGPT和Perplexity等平台的可见性与引用率。通过分析品牌提及、内容可引用性及AI爬虫可访问性，提供针对性的优化策略。','gh_-56537570310025','gh_66207760','search_research','approved','2026-02-20T16:22:28Z','2026-02-20T16:22:28Z','2026-02-20T16:22:28Z','专为AI搜索优化设计，提升网站在Google AI概览、ChatGPT和Perplexity等平台的可见性与引用率。通过分析品牌提及、内容可引用性及AI爬虫可访问性，提供针对性的优化策略。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-agricidaniel-claude-seo-skills-seo-hreflang','skill','seo-hreflang','此技能专注于hreflang标签与国际SEO的审计、验证与生成，能检测常见错误并生成正确的多语言网站实现方案。','gh_-56537570310025','gh_66207760','dev_code','approved','2026-02-20T16:22:29Z','2026-02-20T16:22:29Z','2026-02-20T16:22:29Z','此技能专注于hreflang标签与国际SEO的审计、验证与生成，能检测常见错误并生成正确的多语言网站实现方案。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-agricidaniel-claude-seo-skills-seo-images','skill','seo-images','该技能专注于网站图片的SEO与性能优化，自动检查并分析替代文本、文件大小、格式、响应式图片、延迟加载及布局偏移预防等关键指标。','gh_-56537570310025','gh_66207760','dev_code','approved','2026-02-20T16:22:32Z','2026-02-20T16:22:32Z','2026-02-20T16:22:32Z','该技能专注于网站图片的SEO与性能优化，自动检查并分析替代文本、文件大小、格式、响应式图片、延迟加载及布局偏移预防等关键指标。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-agricidaniel-claude-seo-skills-seo-page','skill','seo-page','针对单个网页进行深度SEO分析，涵盖页面元素、内容质量、技术标签、结构化数据和图片性能，并提供具体优化建议与评分。','gh_-56537570310025','gh_66207760','dev_code','approved','2026-02-20T16:22:33Z','2026-02-20T16:22:33Z','2026-02-20T16:22:33Z','针对单个网页进行深度SEO分析，涵盖页面元素、内容质量、技术标签、结构化数据和图片性能，并提供具体优化建议与评分。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-agricidaniel-claude-seo-skills-seo-plan','skill','seo-plan','为新建或现有网站提供战略性的SEO规划，包含行业模板、竞争分析、内容策略和实施路线图。','gh_-56537570310025','gh_66207760','dev_code','approved','2026-02-20T16:22:35Z','2026-02-20T16:22:35Z','2026-02-20T16:22:35Z','为新建或现有网站提供战略性的SEO规划，包含行业模板、竞争分析、内容策略和实施路线图。',1);
