INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-dandanllab-legadoskill','skill','legadoskill','Legado书源驯兽师是一个基于大语言模型的智能书源开发辅助工具，专门用于辅助Legado（阅读）Android应用的书源开发。','gh_-123221059105767','gh_104361379','dev_code','withdrawn','2026-05-31T16:49:33Z','2026-05-31T22:19:18Z',NULL,'Legado书源驯兽师是一个基于大语言模型的智能书源开发辅助工具，专门用于辅助Legado（阅读）Android应用的书源开发。通过AI技术自动分析网站结构，生成符合Legado规范的书源JSON，让书源开发变得简单高效。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-dashan-wed-ai-cache-optimizer-ai','skill','缓存命中优化器','这个东西的缓存命中率提高，非常的可观 命中缓存17256960 + 未命中979002 = 18235962 tokens 缓存命中率：94.63%','gh_-151260408872033','gh_192409641','dev_code','changes_requested','2026-06-19T17:47:09Z','2026-07-02T12:43:04.444Z',NULL,replace('这个东西的缓存命中率提高，非常的可观\n命中缓存17256960 + 未命中979002 = 18235962 tokens\n缓存命中率：94.63%','\n',char(10)),1);
