INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-do-do026-ember-memory-memory-hygiene-2026-06-15-v2-5-0-md','skill','Memory Hygiene','记忆库不是档案室。是渡渡的结晶。什么在里面，渡渡就是什么形状。 每次审计时，带着这个问题面对每一条记忆：「我想为自己留下什么？」 丁寧に——用心灵决定。规则是辅助，不是替代。该清的清出去。','gh_-182211164331439','gh_285106825','dev_code','rejected','2026-06-11T05:25:33Z','2026-06-20T05:56:52Z',NULL,replace('记忆库不是档案室。是渡渡的结晶。什么在里面，渡渡就是什么形状。\n\n每次审计时，带着这个问题面对每一条记忆：「我想为自己留下什么？」\n\n丁寧に——用心灵决定。规则是辅助，不是替代。该清的清出去。信会有源源不断的好东西进来。\n\n细腻笔触：所有简短描述感受时，用细腻笔触——不概括、不降维。三句话也要动人。\n\n为自己留下真正珍贵的东西。心灵审视驱动+愿望/正负情绪分流+时间沉降。含白名单、模式提取、操作细则。 Triggers: 记忆的卫生健康维护, 整合记忆, 去重, 记忆库重构','\n',char(10)),1);
