INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-firecrawl-firecrawl-claude-plugin-skills-firecrawl-cli','skill','firecrawl-cli','Firecrawl 是一款专为 LLM 优化的网页抓取与搜索工具，能准确高效地提取网页内容并返回结构化的 Markdown 数据，适用于文档阅读、信息检索和深度研究等多种网络任务。','gh_-65315112426442','gh_66207760','search_research','approved','2026-02-20T16:08:57Z','2026-02-20T16:08:57Z','2026-02-20T16:08:57Z','Firecrawl 是一款专为 LLM 优化的网页抓取与搜索工具，能准确高效地提取网页内容并返回结构化的 Markdown 数据，适用于文档阅读、信息检索和深度研究等多种网络任务。',1);
