INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-frmoretto-clarity-gate-claude-skills-clarity-gate','skill','clarity-gate','该技能为RAG系统提供知识库文档摄入前的认知质量验证，确保文档经过适当标注，防止LLM将假设误认为事实。','gh_-36616151602294','gh_66207760','docs_knowledge','approved','2026-02-20T16:08:57Z','2026-02-20T16:08:57Z','2026-02-20T16:08:57Z','该技能为RAG系统提供知识库文档摄入前的认知质量验证，确保文档经过适当标注，防止LLM将假设误认为事实。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-fuqun616-eng-wechat-girlfriend-skill','skill','微信女友','基于微信 ClawBot 桥接沙盒包,做的技能,沙盒包太难做了😭😭😭 💕 微信虚拟女友 AI 技能 让你的 AI 角色卡变成一个会主动记忆、有情绪变化的微信女友。','gh_-46767919634102','gh_275434479','chat_communication','withdrawn','2026-05-08T12:15:52Z','2026-05-10T23:14:25Z',NULL,replace('基于微信 ClawBot 桥接沙盒包,做的技能,沙盒包太难做了😭😭😭\n\n💕 微信虚拟女友 AI 技能\n让你的 AI 角色卡变成一个会主动记忆、有情绪变化的微信女友。\n基于 Operit 平台 的角色卡驱动微信自动回复系统，内置记忆管理、情绪感知、亲密度系统和模式切换。\n功能特性\n角色卡驱动 - 严格遵循角色人设，自动适配语气风格\n记忆系统 - 分层记忆（永久/长期/短期/情绪），自动消逝与整理\n亲密度系统 - 动态评分（0-100），影响称呼和语气亲密度\n持续监控 - 60秒长轮询，自动回复，永不掉线\n调试模式 - 支持 at[...] 标记切换技术助手模式\n安全约束 - 内置内容安全边界，保持角色沉浸感\n定时记忆整理 - 每日凌晨自动清理过期记忆\n快速开始\n安装所需包\n创建角色卡\n运行技能 -> 扫码登录微信\n开始聊天！','\n',char(10)),1);
