INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-orchestra-research-ai-research-skills-01-model-architecture-rwkv','skill','rwkv','RWKV是一种结合RNN与Transformer优势的混合架构，具备线性推理复杂度与无限上下文能力，无需KV缓存，适用于长序列处理与高效推理场景。','gh_-85940618210933','gh_66207760','dev_code','approved','2026-02-20T17:14:47Z','2026-02-20T17:14:47Z','2026-02-20T17:14:47Z','RWKV是一种结合RNN与Transformer优势的混合架构，具备线性推理复杂度与无限上下文能力，无需KV缓存，适用于长序列处理与高效推理场景。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-orchestra-research-ai-research-skills-01-model-architecture-torchtitan','skill','torchtitan','提供基于PyTorch原生框架torchtitan的大规模语言模型分布式预训练能力，支持4D并行（FSDP2、TP、PP、CP）及Float8量化，适用于从8到512+ GPU的Llama、DeepS','gh_-85940618210933','gh_66207760','dev_code','approved','2026-02-20T17:15:15Z','2026-02-20T17:15:15Z','2026-02-20T17:15:15Z','提供基于PyTorch原生框架torchtitan的大规模语言模型分布式预训练能力，支持4D并行（FSDP2、TP、PP、CP）及Float8量化，适用于从8到512+ GPU的Llama、DeepSeek等模型预训练。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-orchestra-research-ai-research-skills-02-tokenization-huggingface-tokenizers','skill','huggingface-tokenizers','基于Rust的高性能分词器，支持BPE、WordPiece和Unigram算法，可训练自定义词表并处理对齐与填充，无缝集成transformers库，适用于研究和生产环境。','gh_-85940618210933','gh_66207760','dev_code','approved','2026-02-20T17:13:39Z','2026-02-20T17:13:39Z','2026-02-20T17:13:39Z','基于Rust的高性能分词器，支持BPE、WordPiece和Unigram算法，可训练自定义词表并处理对齐与填充，无缝集成transformers库，适用于研究和生产环境。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-orchestra-research-ai-research-skills-02-tokenization-sentencepiece','skill','sentencepiece','SentencePiece是一款语言无关的文本分词器，将文本视为原始Unicode处理，支持BPE和Unigram算法。','gh_-85940618210933','gh_66207760','dev_code','approved','2026-02-20T17:14:54Z','2026-02-20T17:14:54Z','2026-02-20T17:14:54Z','SentencePiece是一款语言无关的文本分词器，将文本视为原始Unicode处理，支持BPE和Unigram算法。它速度快、内存占用小，支持多语言及CJK文字，无需预分词即可训练，被T5、ALBERT等模型广泛使用。',1);
