INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-orchestra-research-ai-research-skills-07-safety-alignment-llamaguard','skill','llamaguard','LlamaGuard是Meta开发的7-8B参数内容安全审核模型，用于LLM输入/输出过滤，覆盖六大安全类别，准确率达94-95%，支持vLLM、HuggingFace和NeMo Guardrails','gh_-85940618210933','gh_66207760','dev_code','approved','2026-02-20T17:13:57Z','2026-02-20T17:13:57Z','2026-02-20T17:13:57Z','LlamaGuard是Meta开发的7-8B参数内容安全审核模型，用于LLM输入/输出过滤，覆盖六大安全类别，准确率达94-95%，支持vLLM、HuggingFace和NeMo Guardrails集成部署。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-orchestra-research-ai-research-skills-07-safety-alignment-nemo-guardrails','skill','nemo-guardrails','NVIDIA NeMo Guardrails 为LLM应用提供运行时安全框架，具备越狱检测、输入输出验证、事实核查、幻觉检测、PII过滤和毒性检测等功能，使用Colang 2.','gh_-85940618210933','gh_66207760','dev_code','approved','2026-02-20T17:14:23Z','2026-02-20T17:14:23Z','2026-02-20T17:14:23Z','NVIDIA NeMo Guardrails 为LLM应用提供运行时安全框架，具备越狱检测、输入输出验证、事实核查、幻觉检测、PII过滤和毒性检测等功能，使用Colang 2.0 DSL实现可编程安全护栏，生产就绪且支持T4 GPU运行。',1);
