INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-github-com-yangchuansheng-visual-ip-illustrations','skill','visual-ip-illustrations','Visual IP Illustrations 引导 AI agent 为文章、帖子、博客、Notion 文档和方法论写作创建正文配图。','gh_-227269446500487','gh_49579515','dev_code','approved','2026-06-25T12:26:14Z','2026-07-02T13:13:49.228Z','2026-07-02T13:13:49.228Z',replace('Visual IP Illustrations 引导 AI agent 为文章、帖子、博客、Notion 文档和方法论写作创建正文配图。\n\n这个 skill 会读取源文本里的认知锚点，再把一个判断、工作流、结构、状态或隐喻转化为一张易记的 16:9 手绘解释图。\n核心价值：用户可以选择一个视觉 IP，并得到在角色、风格规则、提示词、QA 门槛、保存输出、署名、来源上下文和品牌边界上都与该 IP 保持一致的文章配图资产。\n适合:\n需要为文章概念制作正文配图的作者。\n想要清晰视觉隐喻的产品思考者和方法论写作者。\n需要可复用视觉语言提示词的 AI 工作流作者。','\n',char(10)),1);
