INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-debug-msg-dump','package','消息调试转储','将每次发送给模型的完整消息列表保存到文件，用于调试。 保存路径为/storage/emulated/0/Download/Operit/debug_msg_dump/，如果无此路径，自动生成...','gh_143613684','gh_143613684','system_data','withdrawn','2026-04-20T10:04:52Z','2026-07-22T03:12:17.659Z','2026-04-20T10:04:52Z',replace('将每次发送给模型的完整消息列表保存到文件，用于调试。\n保存路径为/storage/emulated/0/Download/Operit/debug_msg_dump/，如果无此路径，自动生成。\n保存文件为两份，history开头为上下文全文，finalize开头为经过上下文插件包删改后文件。\n\n仅仅是为了测试楼层限制器，让小助手编写的功能。\n作者代码白痴，大概率有问题（如功能不完全），请在知晓此前提下使用\n\n如有bug请联系\n小红书@黒羽燕','\n',char(10)),1);
