INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-music-studio','script','music_studio','让机写电子音乐~ ✓基于 Strudel（TidalCycles 的 JS 版本）生成可播放的音乐页面 ✓支持的音乐风格**：Techno、House、Lo-fi、Ambient、Synthwa...','gh_250852253','gh_250852253','media_content','withdrawn','2026-04-24T18:33:40Z','2026-07-22T09:43:27.678Z','2026-04-24T18:34:21Z',replace('让机写电子音乐~\n\n✓基于 Strudel（TidalCycles 的 JS 版本）生成可播放的音乐页面\n\n✓支持的音乐风格**：Techno、House、Lo-fi、Ambient、Synthwave、DnB、Jazz……\n-72种鼓机+128种GM乐器+ 内置合成器\n-完整效果链：滤波器、混响、延迟、FM合成\n-生成可编辑的 Strudel REPL：operit可以直接预览收听~，可以直接改代码\n\n✓用法：告诉 AI 你想要什么风格的音乐，它会自动写代码并生成播放页面。\n\n✓示例：「写一首 Lo-fi 风格的深夜学习音乐」「来一段 Techno 鼓点」「写一首 Ambient 氛围音乐」','\n',char(10)),1);
