INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-deepthinking-artifact-1-0-0','script','深度思考','实现完整的六维深度思考框架，包括本质五连问、时空解构法、三维验证锁、认知进化器、纠错双机制和四维价值尺。这是AI的内部思考辅助工具，用于分析问题根源，产出结构化洞察后给出简洁回答。不要将分析过程直接展示给用户。','gh_277503719','gh_277503719','other','rejected','2026-07-04T02:38:33.465Z','2026-07-05T05:10:39.599Z',NULL,'',0);
