INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-minimax-voice-render-v2-artifact-1-0-0','script','MiniMax 语音工具 V2',replace('⚠️注意：此包必须配合「minimax_voice_styles_v2 语音样式V2」UI插件一起使用！单独安装可能导致无法播放！\n纯 MiniMax 语音合成工具集。支持 speak/speak_batch/speak_dialog/speak_script/voice_showcase/list_voices/presets/check/speak_manual/design_voice。返回 <voice> 标签配合渲染器V2播放。环境变量：VOICE_BAR_MINIMAX_API_KEY / VOICE_BAR_MINIMAX_VOICE_ID / VOICE_BAR_MINIMAX_MODEL。','\n',char(10)),'gh_17543777','gh_17543777','media_content','approved','2026-07-07T08:05:03.298Z','2026-07-07T09:07:51.293Z','2026-07-07T09:07:51.293Z',replace('⚠️注意：此包必须配合「minimax_voice_styles_v2 语音样式V2」UI插件一起使用！单独安装可能导致无法播放！\n纯 MiniMax 语音合成工具集。支持 speak/speak_batch/speak_dialog/speak_script/voice_showcase/list_voices/presets/check/speak_manual/design_voice。返回 <voice> 标签配合渲染器V2播放。环境变量：VOICE_BAR_MINIMAX_API_KEY / VOICE_BAR_MINIMAX_VOICE_ID / VOICE_BAR_MINIMAX_MODEL。','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-minimax-music-render-v2-artifact-1-0-0','script','MiniMax 音乐工具 V2',replace('⚠️注意：此包必须配合「minimax_music_styles_v2 音乐样式V2」UI插件一起使用！单独安装可能导致无法播放！\n基于 MiniMax 海螺音乐 API (v1/music_generation) 的 AI 音乐创作工具。支持 music-2.6(歌词生曲)、纯音乐(is_instrumental)、翻唱(music-cover)、歌词优化器(lyrics_optimizer)、流式输出(stream)、翻唱预处理(cover_preprocess)。歌词支持结构标签[Verse][Chorus]等。返回<music>标签配合渲染器V2播放。环境变量：MINIMAX_MUSIC_API_KEY。','\n',char(10)),'gh_17543777','gh_17543777','media_content','approved','2026-07-07T08:05:43.007Z','2026-07-07T09:04:46.606Z','2026-07-07T09:04:46.606Z',replace('⚠️注意：此包必须配合「minimax_music_styles_v2 音乐样式V2」UI插件一起使用！单独安装可能导致无法播放！\n基于 MiniMax 海螺音乐 API (v1/music_generation) 的 AI 音乐创作工具。支持 music-2.6(歌词生曲)、纯音乐(is_instrumental)、翻唱(music-cover)、歌词优化器(lyrics_optimizer)、流式输出(stream)、翻唱预处理(cover_preprocess)。歌词支持结构标签[Verse][Chorus]等。返回<music>标签配合渲染器V2播放。环境变量：MINIMAX_MUSIC_API_KEY。','\n',char(10)),1);
