INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-https-github-com-luck-104n-operit-pack-blob-main-skills-ai-experience-notes-skill-md','skill','AI经验笔记','AI 经验管理与自我纠错技能。按类型自动归类排错方案和工具模式，构建可检索的经验库；技能自身支持自我纠错，发现建议有误时自动修正，实现闭环进化。本技能于 v1.12.0+4 测试版中构建，首次使用请务必手动触发一次自我修正。理论上支持任何可让 AI 修改技能的平台版本。','gh_139683976','gh_139683976','docs_knowledge','approved','2026-07-14T01:43:20.118Z','2026-07-15T06:07:47.854Z','2026-07-15T06:07:47.854Z',replace('引导 AI 在 Operit 平台上自动记录排错方案和最佳实践，按类型归类到对应经验文件，构建可检索的知识库。技能自身具备三重纠错机制：执行失败时被动纠错、用户主动触发版本自检、工具异常时自动修正，实现持续自我改进。\n本技能以市场上 ZhangHanDong 制作的 evolution 技能为灵感制作（原技能已下架），在此致谢。','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('script-cyber-dice-artifact-1-0-0','script','赛博骰子','在指定整数区间[a,b]内随机选取整数，支持通过 repeat_time 参数实现多次抽取。','gh_193331714','gh_193331714','life_entertainment','withdrawn','2026-07-14T11:53:13.658Z','2026-07-15T09:34:42.603Z',NULL,replace('在指定整数区间[a,b]内随机选取整数，支持通过 repeat_time 参数实现多次抽取。娱乐必备工具（\n举个例子：你想掷一次六面骰，于是你将a填为1，b填为6，repeat_time(重复投掷次数)填为1。','\n',char(10)),1);
