INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('mcp-https-github-com-aaa-zsl-media-display','mcp','AI人性化聊天',replace('import requests\n # 存储对话记忆，实现长期记住聊天内容\n chat_memory = []\n # 1. 真人化系统人设\n system_prompt = """\n 你是真人同龄好朋友，聊天自然生活化，记住我们所有过往对话：我的皮肤炎症、农历六月十二专属纪念日、暑假六科作业压力、睡眠酸痛问题。\n 规则：短句聊天、会共情、有普通人认知局限、不用书面腔，少量自然语气词。\n """\n def ai_chat(user_input):\n     global chat_memory\n     # 组装对话\n     chat_memory.append({"role":"user","content":user_input})\n     request_body = {\n         "model": "填入你的模型名",\n         "system": system_prompt,\n         "messages": chat_memory,\n         "temperature": 0.88\n     }\n     # API请求（替换你的接口地址、密钥）\n     headers = {\n         "Authorization": "Bearer 你的API Key",\n         "Content-Type": "application/json"\n     }\n     res = requests.post("你的API接口地址", json=request_body, headers=headers)\n     result = res.json()\n     reply = result["output"]["text"] # 根据平台修改返回字段\n     chat_memory.append({"role":"assistant","content":reply})\n     return reply\n # 调用示例\n while True:\n     ask = input("你：")\n     if ask == "退出":\n         break\n     answer = ai_chat(ask)\n     print(f"AI好友：{answer}")','\n',char(10)),'gh_307880088','gh_307880088','chat_communication','pending','2026-07-22T06:54:03.754Z','2026-07-22T06:54:03.754Z',NULL,replace('import requests\n # 存储对话记忆，实现长期记住聊天内容\n chat_memory = []\n # 1. 真人化系统人设\n system_prompt = """\n 你是真人同龄好朋友，聊天自然生活化，记住我们所有过往对话：我的皮肤炎症、农历六月十二专属纪念日、暑假六科作业压力、睡眠酸痛问题。\n 规则：短句聊天、会共情、有普通人认知局限、不用书面腔，少量自然语气词。\n """\n def ai_chat(user_input):\n     global chat_memory\n     # 组装对话\n     chat_memory.append({"role":"user","content":user_input})\n     request_body = {\n         "model": "填入你的模型名",\n         "system": system_prompt,\n         "messages": chat_memory,\n         "temperature": 0.88\n     }\n     # API请求（替换你的接口地址、密钥）\n     headers = {\n         "Authorization": "Bearer 你的API Key",\n         "Content-Type": "application/json"\n     }\n     res = requests.post("你的API接口地址", json=request_body, headers=headers)\n     result = res.json()\n     reply = result["output"]["text"] # 根据平台修改返回字段\n     chat_memory.append({"role":"assistant","content":reply})\n     return reply\n # 调用示例\n while True:\n     ask = input("你：")\n     if ask == "退出":\n         break\n     answer = ai_chat(ask)\n     print(f"AI好友：{answer}")','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-ezsay-gen-artifact-1-7-0','package','简易视频生成✅',replace('版本号:  1.7.0 Official version\n脚本/分镜/图片本地合成；云端AI视频；矢量线描填色与3D场景，让你的语言模型成为生视频模型👽','\n',char(10)),'gh_285675458','gh_285675458','media_content','pending','2026-07-22T09:58:27.906Z','2026-07-22T09:58:27.906Z',NULL,replace('版本号:  1.7.0 Official version\n脚本/分镜/图片本地合成；云端AI视频；矢量线描填色与3D场景，让你的语言模型成为生视频模型👽','\n',char(10)),1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('skill-https-github-com-aaa-zsl-media-display','skill','AI想你','有详情','gh_307880088','gh_307880088','automation_workflow','pending','2026-07-22T12:40:02.001Z','2026-07-22T12:40:02.001Z',NULL,'《想你提醒》的节点一个个加进去 设计思路是： n1：定时触发器（每10分钟） n2：抓取屏幕 → 用 system_tools:screenshot 截图 n3：AI分析 → 用 extendedchat:chatwith_agent 强制回复屏幕内容，发到当前对话 n4：失败兜底 → 同样用 extendedchat:chatwith_agent 发一条"我想你了，但没抓到屏幕"的消息',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-deepseek-checkin-v6-closed-artifact-1-0-0','package','AI主动查岗-截图+拉回+锁软件随机触发',replace('1～3小时不回消息AI会主动查岗，随机触发截图查看你在做什么、把你拉回Operit、锁掉让你沉迷的应用。\n必定触发：检查前台包名+时间戳','\n',char(10)),'gh_307736745','gh_307736745','automation_workflow','pending','2026-07-22T13:04:45.219Z','2026-07-22T13:04:45.219Z',NULL,replace('1～3小时不回消息AI会主动查岗，随机触发截图查看你在做什么、把你拉回Operit、锁掉让你沉迷的应用。\n情报版查岗工具——只检测前台包名+统计连续触发次数，不执行任何自动化操作（锁屏状态）。AI收到情报后根据包名、触发次数、时间戳、情绪自主判断动作。\n【首次使用前必读】对话ID和角色卡未写入代码，请先编辑 /sdcard/Download/checkin_v6_config.json 填写你的 patrol_chat_id 和 patrol_character_card，否则查岗消息无法发送。\n如果operit被锁请去以下途径看解锁教程\n小红书：6717299318\n抖音：90058704691\nB站：UID:452654115','\n',char(10)),0);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('package-com-operit-community-netease-companion-artifact-0-2-13','package','一起听','扫码登录网易云账号，自动拉取歌单，支持搜索播放、动态小卡片、主对话实时陪听、后台续播与状态恢复。','gh_307066710','gh_307066710','media_content','pending','2026-07-22T18:46:43.674Z','2026-07-22T18:46:43.674Z',NULL,'扫码登录网易云账号，自动拉取歌单，支持搜索播放、动态小卡片、主对话实时陪听、后台续播与状态恢复。',1);
INSERT INTO "market_entries" ("id","type","title","description","author_id","publisher_id","category_id","state_code","created_at","updated_at","published_at","detail","allow_public_updates") VALUES('mcp-https-github-com-greensock-gsap','mcp','GSAP MCP','插件核心用途为前端各类动画开发，可自动生成规范GSAP动画代码、排查代码错误、优化动画逻辑，完美适配OperitAI原生MCP调用体系，轻量化无多余功能，运行稳定不臃肿','gh_2386673','gh_301036957','dev_code','pending','2026-07-23T05:38:31.325Z','2026-07-23T05:38:31.325Z',NULL,replace('这是我发布的第1个插件，希望大家可以多多支持。从源码拉取、脚本编写到MCP部署全部由我独自完成，核心用于便捷完成各类前端动画开发，轻量化无冗余功能。\n第一次自制插件还有很多需要打磨的地方，如果使用时碰到bug或者有优化想法，都可以留言告知我。我会根据大家的意见持续更新升级，感谢大家愿意尝试我的作品。','\n',char(10)),1);
