INSERT INTO "repo_plugin_versions" ("id","version_id","ref_type","ref_name","commit_sha","install_config","created_at","updated_at") VALUES('mcp-issue-65-v-v1-repo','mcp-issue-65-v-v1','branch','unknown','',replace('{\n  "mcpServers": {\n    "my-memory": {\n      "command": "python",\n      "args": ["-c", "import http.server, json, urllib.request\nclass H(http.server.BaseHTTPRequestHandler):\n def do_GET(s):\n  req=urllib.request.Request(''http://192.168.0.100:8080/health'')\n  with urllib.request.urlopen(req) as r:\n   d=json.loads(r.read())\n  s.send_response(200)\n  s.end_headers()\n  s.wfile.write(json.dumps(d).encode())\n def do_POST(s):\n  l=int(s.headers.get(''Content-Length'',0))\n  b=s.rfile.read(l)\n  s.send_response(200)\n  s.end_headers()\n  s.wfile.write(b''{\"status\":\"ok\"}'')\nhttp.server.HTTPServer((''localhost'',8081),H).serve_forever()"]\n    }\n  }\n}','\n',char(10)),'2026-06-26T13:37:35.822Z','2026-06-26T13:37:35.822Z');
