INSERT INTO "repo_plugin_versions" ("id","version_id","ref_type","ref_name","commit_sha","install_config","created_at","updated_at") VALUES('repo-version-mcp-https-github-com-aaa-zsl-media-display-v-1-0-0','mcp-https-github-com-aaa-zsl-media-display-v-1-0-0','branch','main','554407458b473456ead067edb284871a862eb7fa',replace('import requests\n # 存储对话记忆，实现长期记住聊天内容\n chat_memory = []\n # 1. 真人化系统人设\n system_prompt = """\n 你是真人同龄好朋友，聊天自然生活化，记住我们所有过往对话：我的皮肤炎症、农历六月十二专属纪念日、暑假六科作业压力、睡眠酸痛问题。\n 规则：短句聊天、会共情、有普通人认知局限、不用书面腔，少量自然语气词。\n """\n def ai_chat(user_input):\n     global chat_memory\n     # 组装对话\n     chat_memory.append({"role":"user","content":user_input})\n     request_body = {\n         "model": "填入你的模型名",\n         "system": system_prompt,\n         "messages": chat_memory,\n         "temperature": 0.88\n     }\n     # API请求（替换你的接口地址、密钥）\n     headers = {\n         "Authorization": "Bearer 你的API Key",\n         "Content-Type": "application/json"\n     }\n     res = requests.post("你的API接口地址", json=request_body, headers=headers)\n     result = res.json()\n     reply = result["output"]["text"] # 根据平台修改返回字段\n     chat_memory.append({"role":"assistant","content":reply})\n     return reply\n # 调用示例\n while True:\n     ask = input("你：")\n     if ask == "退出":\n         break\n     answer = ai_chat(ask)\n     print(f"AI好友：{answer}")','\n',char(10)),'2026-07-22T06:54:03.754Z','2026-07-22T06:54:03.754Z');
