PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE market_meta (
  key         TEXT PRIMARY KEY,
  value       TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);
CREATE TABLE market_types (
  id              TEXT PRIMARY KEY,
  slug            TEXT NOT NULL UNIQUE,
  name            TEXT NOT NULL,
  description     TEXT,
  sort_order      INTEGER NOT NULL DEFAULT 0,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE TABLE market_format_versions (
  id                 TEXT PRIMARY KEY,
  type               TEXT NOT NULL,
  name               TEXT NOT NULL,
  description        TEXT,
  publishable        INTEGER NOT NULL DEFAULT 1,
  legacy_importable  INTEGER NOT NULL DEFAULT 0,
  sort_order         INTEGER NOT NULL DEFAULT 0,
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL,
  FOREIGN KEY(type) REFERENCES market_types(slug)
);
CREATE TABLE market_state_codes (
  code          TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  description   TEXT,
  public_listed INTEGER NOT NULL DEFAULT 0,
  sort_order    INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE market_reason_codes (
  code              TEXT PRIMARY KEY,
  scope             TEXT NOT NULL DEFAULT 'review',
  legacy_label      TEXT UNIQUE,
  default_state_code TEXT,
  name              TEXT NOT NULL,
  description       TEXT,
  sort_order        INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE market_authors (
  id                  TEXT PRIMARY KEY,
  github_id           INTEGER NOT NULL UNIQUE,
  github_login        TEXT NOT NULL,
  owner_avatar        TEXT,
  status              TEXT NOT NULL DEFAULT 'active',
  blocked_reason_code TEXT,
  blocked_at          TEXT,
  blocked_by          TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  FOREIGN KEY(blocked_reason_code) REFERENCES market_reason_codes(code)
);
CREATE TABLE market_entries (
  id              TEXT PRIMARY KEY,
  type            TEXT NOT NULL,
  title           TEXT NOT NULL,
  description     TEXT NOT NULL,
  author_id       TEXT NOT NULL,
  publisher_id    TEXT NOT NULL,
  category_id     TEXT,
  state_code      TEXT NOT NULL DEFAULT 'pending',
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  published_at    TEXT, detail TEXT NOT NULL DEFAULT "", allow_public_updates INTEGER NOT NULL DEFAULT 1,
  FOREIGN KEY(type) REFERENCES market_types(slug),
  FOREIGN KEY(author_id) REFERENCES market_authors(id),
  FOREIGN KEY(publisher_id) REFERENCES market_authors(id),
  FOREIGN KEY(category_id) REFERENCES market_categories(id),
  FOREIGN KEY(state_code) REFERENCES market_state_codes(code)
);
CREATE TABLE market_versions (
  id              TEXT PRIMARY KEY,
  entry_id        TEXT NOT NULL,
  version         TEXT NOT NULL,
  format_ver      TEXT NOT NULL,
  min_app_ver     TEXT NOT NULL,
  max_app_ver     TEXT,
  state_code      TEXT NOT NULL DEFAULT 'pending',
  changelog       TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  published_at    TEXT, runtime_pkg TEXT, publisher_id TEXT,
  FOREIGN KEY(entry_id) REFERENCES market_entries(id) ON DELETE CASCADE,
  FOREIGN KEY(format_ver) REFERENCES market_format_versions(id),
  FOREIGN KEY(state_code) REFERENCES market_state_codes(code),
  UNIQUE(entry_id, version)
);
CREATE TABLE market_version_reasons (
  version_id  TEXT NOT NULL,
  reason_code TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  PRIMARY KEY(version_id, reason_code),
  FOREIGN KEY(version_id) REFERENCES market_versions(id) ON DELETE CASCADE,
  FOREIGN KEY(reason_code) REFERENCES market_reason_codes(code)
);
CREATE TABLE repo_plugin_specs (
  id              TEXT PRIMARY KEY,
  entry_id        TEXT NOT NULL UNIQUE,
  source_kind     TEXT NOT NULL,
  source_url      TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  FOREIGN KEY(entry_id) REFERENCES market_entries(id) ON DELETE CASCADE
);
CREATE TABLE repo_plugin_versions (
  id              TEXT PRIMARY KEY,
  version_id      TEXT NOT NULL UNIQUE,
  ref_type        TEXT NOT NULL,
  ref_name        TEXT NOT NULL,
  commit_sha      TEXT NOT NULL,
  install_config  TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  FOREIGN KEY(version_id) REFERENCES market_versions(id) ON DELETE CASCADE
);
CREATE TABLE market_assets (
  id              TEXT PRIMARY KEY,
  version_id      TEXT NOT NULL,
  kind            TEXT NOT NULL,
  url             TEXT NOT NULL,
  gh_owner        TEXT,
  gh_repo         TEXT,
  gh_release_tag  TEXT,
  asset_name      TEXT,
  sha256          TEXT,
  size_bytes      INTEGER,
  content_type    TEXT,
  created_at      TEXT NOT NULL,
  FOREIGN KEY(version_id) REFERENCES market_versions(id) ON DELETE CASCADE
);
CREATE TABLE market_categories (
  id              TEXT PRIMARY KEY,
  name            TEXT NOT NULL,
  description     TEXT,
  sort_order      INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE market_curations (
  id          TEXT PRIMARY KEY,
  list_key    TEXT NOT NULL,
  entry_id    TEXT NOT NULL,
  position    INTEGER NOT NULL DEFAULT 0,
  note        TEXT,
  starts_at   TEXT,
  ends_at     TEXT,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  FOREIGN KEY(entry_id) REFERENCES market_entries(id) ON DELETE CASCADE
);
CREATE TABLE market_comments (
  id              TEXT PRIMARY KEY,
  entry_id        TEXT NOT NULL,
  parent_id       TEXT,
  author_id       TEXT NOT NULL,
  body            TEXT NOT NULL,
  source          TEXT NOT NULL,
  legacy_issue    INTEGER,
  legacy_comment  INTEGER,
  status          TEXT NOT NULL DEFAULT 'active',
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  FOREIGN KEY(entry_id) REFERENCES market_entries(id) ON DELETE CASCADE,
  FOREIGN KEY(author_id) REFERENCES market_authors(id)
);
CREATE TABLE market_reaction_counts (
  id            TEXT PRIMARY KEY,
  entry_id      TEXT NOT NULL,
  reaction      TEXT NOT NULL,
  gh_count      INTEGER NOT NULL DEFAULT 0,
  cf_count      INTEGER NOT NULL DEFAULT 0,
  total_count   INTEGER NOT NULL DEFAULT 0,
  updated_at    TEXT NOT NULL,
  UNIQUE(entry_id, reaction)
);
CREATE TABLE market_mutation_log (
  id             TEXT PRIMARY KEY,
  mutation_id    TEXT NOT NULL,
  actor_id       TEXT NOT NULL,
  actor_role     TEXT NOT NULL,
  reason         TEXT NOT NULL,
  object_count   INTEGER NOT NULL DEFAULT 0,
  created_at     TEXT NOT NULL
);
CREATE TABLE market_dirty_projections (
  projection     TEXT NOT NULL,
  scope_key      TEXT NOT NULL,   -- hash/stable key of the scope
  reason         TEXT NOT NULL,
  last_mutation_id TEXT NOT NULL,
  updated_at     TEXT NOT NULL,
  PRIMARY KEY (projection, scope_key)
);
CREATE TABLE market_entry_stats (
  entry_id          TEXT PRIMARY KEY,
  type              TEXT NOT NULL,
  legacy_downloads  INTEGER NOT NULL DEFAULT 0,
  legacy_likes      INTEGER NOT NULL DEFAULT 0,
  cf_downloads      INTEGER NOT NULL DEFAULT 0,
  cf_likes          INTEGER NOT NULL DEFAULT 0,
  downloads_total   INTEGER NOT NULL DEFAULT 0,
  likes_total       INTEGER NOT NULL DEFAULT 0,
  last_download_at  TEXT,
  last_like_at      TEXT,
  updated_at        TEXT NOT NULL,
  FOREIGN KEY(entry_id) REFERENCES market_entries(id) ON DELETE CASCADE
);
CREATE TABLE market_analytics_aggregate_windows (
  id            TEXT PRIMARY KEY,
  window_start  TEXT NOT NULL,
  window_end    TEXT NOT NULL,
  downloads     INTEGER NOT NULL DEFAULT 0,
  likes         INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "artifact_projects" (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL UNIQUE, project_key TEXT NOT NULL, runtime_pkg TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(entry_id) REFERENCES market_entries(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE IF NOT EXISTS "market_notifications" (
  id          TEXT PRIMARY KEY,
  recipient   TEXT NOT NULL,
  kind        TEXT NOT NULL,
  entry_id    TEXT,
  comment_id  TEXT,
  actor_id    TEXT NOT NULL,
  title       TEXT NOT NULL,
  body        TEXT NOT NULL DEFAULT '',
  created_at  TEXT NOT NULL,
  FOREIGN KEY(recipient) REFERENCES market_authors(id),
  FOREIGN KEY(entry_id) REFERENCES market_entries(id),
  FOREIGN KEY(comment_id) REFERENCES market_comments(id)
);
CREATE TABLE github_oauth_transactions (
  id TEXT PRIMARY KEY,
  state TEXT NOT NULL UNIQUE,
  delivery_secret_hash TEXT NOT NULL,
  code_verifier TEXT NOT NULL,
  status TEXT NOT NULL,
  encrypted_payload TEXT,
  payload_iv TEXT,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  completed_at INTEGER,
  client_ip_hash TEXT
, completion_redirect_uri TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_fv_type ON market_format_versions(type, sort_order);
CREATE INDEX idx_authors_status ON market_authors(status, updated_at DESC);
CREATE INDEX idx_authors_login ON market_authors(github_login);
CREATE UNIQUE INDEX idx_entries_type_id ON market_entries(type, id);
CREATE INDEX idx_entries_public ON market_entries(type, state_code, updated_at DESC);
CREATE INDEX idx_entries_author ON market_entries(author_id, updated_at DESC);
CREATE INDEX idx_entries_publisher ON market_entries(publisher_id, updated_at DESC);
CREATE INDEX idx_versions_entry ON market_versions(entry_id, published_at DESC);
CREATE INDEX idx_versions_public ON market_versions(entry_id, state_code, published_at DESC);
CREATE UNIQUE INDEX idx_repo_plugin_source ON repo_plugin_specs(source_url);
CREATE INDEX idx_curations_list ON market_curations(list_key, position);
CREATE UNIQUE INDEX idx_curations_unique ON market_curations(list_key, entry_id);
CREATE INDEX idx_mutation_log_created ON market_mutation_log(created_at DESC);
CREATE INDEX idx_entry_stats_type ON market_entry_stats(type, downloads_total DESC, likes_total DESC);
CREATE INDEX idx_analytics_windows_end ON market_analytics_aggregate_windows(window_end DESC);
CREATE UNIQUE INDEX idx_artifact_project_key ON artifact_projects(project_key);
CREATE INDEX idx_notifications_recipient ON market_notifications(recipient, created_at DESC);
CREATE INDEX idx_github_oauth_transactions_expiry
  ON github_oauth_transactions(expires_at);
CREATE INDEX idx_github_oauth_transactions_rate_limit
  ON github_oauth_transactions(client_ip_hash, created_at);
